def findMaximumNum(str, K):
    def backtrack(s, k, max_num):
        if k == 0:
            if int(s) > int(max_num[0]):
                max_num[0] = s
            return
        for i in range(len(s)):
            for j in range(i + 1, len(s)):
                s_list = list(s)
                s_list[i], s_list[j] = s_list[j], s_list[i]
                new_s = ''.join(s_list)
                if int(new_s) > int(max_num[0]):
                    backtrack(new_s, k - 1, max_num)
    max_num = ['0']
    backtrack(str, K, max_num)
    return max_num[0]
